-- Exact inspected UPDATE OF predicates and trigger names/order.
CREATE TRIGGER enforce_receivable_gateway_submission_fence BEFORE UPDATE OF gateway_submission_channel, gateway_submission_status, gateway_cnab_file_id, gateway_financial_terms, gateway_financial_terms_confirmed_at, gateway_boleto_issued_at, gateway_payment_id, gateway_payment_link_id, gateway_boleto_linha_digitavel, gateway_boleto_codigo_barras, gateway_invoice_url, gateway_bank_slip_url ON public.contas_receber FOR EACH ROW EXECUTE FUNCTION enforce_receivable_gateway_submission_fence();
CREATE TRIGGER guard_manual_cycle_reviewed_identity BEFORE UPDATE OF id, cliente_id, matricula_id, turma_id, polo_id, tipo_lancamento, origem_cronograma_id, parcela_numero, valor, data_vencimento ON public.contas_receber FOR EACH ROW EXECUTE FUNCTION internal_academic.guard_manual_cycle_reviewed_identity();
CREATE TRIGGER guard_manual_technical_receivable_first_bank_claim BEFORE UPDATE OF gateway_creation_token, gateway_cnab_file_id, gateway_submission_channel, gateway_submission_status ON public.contas_receber FOR EACH ROW WHEN ((new.regra_financeira_renegociacao_snapshot IS NULL)) EXECUTE FUNCTION internal_academic.guard_manual_technical_receivable_first_bank_claim();
CREATE TRIGGER guard_technical_receivable_policy_snapshot BEFORE INSERT OR UPDATE OF regra_financeira_tecnica_snapshot, valor, matricula_id, tipo_lancamento ON public.contas_receber FOR EACH ROW EXECUTE FUNCTION internal_academic.guard_technical_receivable_policy_snapshot();
